// `pnpm unwired coverage` merges its inputs over the Node suite's map: an entry any input executed is executed, only
// production source is listed, and a harness process's hits never count.
import { execFileSync } from "node:child_process";
import { mkdirSync, writeFileSync } from "node:fs";
import { stripTypeScriptTypes } from "node:module";
import { join } from "node:path";
import process from "node:process";
import { pathToFileURL } from "node:url";
import { expect, test } from "@orb/testkit/tooling";
import { inheritedProcessEnv } from "@orb/tooling/floor/process/process-env";
import { transformWithOxc } from "vite";
import type { CoverageRange } from "../../../tooling/src/floor/testing/coverage-collection.ts";
import { COVERAGE_LAYOUT, flattenHits, sourceFileName } from "../../../tooling/src/floor/testing/coverage-collection.ts";
import { convertBrowserRun, convertNodeRun, istanbulOf } from "../../../tooling/src/unwired/coverage-convert.ts";
import { isProductionSource, mergeCoverage } from "../../../tooling/src/unwired/coverage-merge.ts";

const SOURCE = "packages/demo/src/pick.ts";
const TEXT = [
  "export function pick(x: number): number {",
  "  if (x > 0) {",
  "    return 1;",
  "  }",
  "  return 2;",
  "}",
  "export function spare(): number {",
  "  return 3;",
  "}",
  "",
].join("\n");

// The ranges V8 reports for one run of the file: the script, `pick` with its untaken tail or block, and `spare`.
function run(opts: { readonly positive: boolean; readonly spare: boolean }): CoverageRange[] {
  const pickStart = TEXT.indexOf("export function pick") + "export ".length;
  const pickEnd = TEXT.indexOf("}\nexport function spare") + 1;
  const block = TEXT.indexOf("{\n    return 1");
  const blockEnd = TEXT.indexOf("}\n  return 2") + 1;
  const spareStart = TEXT.indexOf("function spare");
  const range = (startOffset: number, endOffset: number, count: number): CoverageRange => ({ startOffset, endOffset, count });
  return [
    range(0, TEXT.length, 1),
    range(pickStart, pickEnd, 1),
    opts.positive ? range(blockEnd, pickEnd - 1, 0) : range(block, blockEnd, 0),
    range(spareStart, TEXT.length - 1, opts.spare ? 1 : 0),
  ];
}

function converted(root: string, ranges: readonly CoverageRange[]): ReturnType<typeof istanbulOf> {
  const path = join(root, SOURCE);
  const segments = flattenHits([{ functionName: "", isBlockCoverage: true, ranges }]);
  return istanbulOf(pathToFileURL(path).href, stripTypeScriptTypes(TEXT, { mode: "strip" }), segments);
}

test("a function or branch arm one input ran and another did not counts as executed", { timeout: 30_000 }, async ({ plantedTree }) => {
  const root = await plantedTree({ [SOURCE]: TEXT });
  const node = await converted(root, run({ positive: true, spare: false }));
  const ct = await converted(root, run({ positive: false, spare: true }));
  const alone = mergeCoverage(root, [{ suite: "node", map: node }]);
  expect(alone.unexecuted).toEqual([{ file: SOURCE, functions: [{ name: "spare", line: 7 }], branches: [{ type: "if", line: 2, arm: 1 }] }]);
  const merged = mergeCoverage(root, [
    { suite: "node", map: node },
    { suite: "ct", map: ct },
  ]);
  expect(merged.unexecuted).toEqual([]);
  expect(merged.totals).toEqual({ files: 1, functions: 2, functionsUnexecuted: 0, branchArms: 2, branchArmsUnexecuted: 0 });
  expect(merged.projections.ct?.unmatchedFunctions).toBe(0);
});

test("only production source under packages/*/src is in scope", () => {
  const generatedHead = (rel: string): string => (rel.endsWith("table.ts") ? "// GENERATED by a script; do not hand-edit.\n" : "export const x = 1;\n");
  const inScope = [
    "packages/kit/src/ids/index.ts",
    "packages/client/src/app.tsx",
    "packages/kit/src/ids/types.d.ts",
    "packages/ui/src/tokens/themes.gen.ts",
    "packages/plugin-toolchain/src/support.generated.ts",
    "packages/kit/src/handle-key/table.ts",
    "packages/client/vite.config.ts",
    "packages/client/node_modules/x/src/a.ts",
    "tests/kit/ids.test.ts",
    "tooling/src/unwired/run.ts",
  ].filter((rel) => isProductionSource(rel, generatedHead));
  expect(inScope).toEqual(["packages/kit/src/ids/index.ts", "packages/client/src/app.tsx"]);
});

test("a process that loaded harness code contributes no hits, a product process does", { timeout: 30_000 }, async ({ plantedTree }) => {
  const root = await plantedTree({ [SOURCE]: TEXT, "tooling/src/stack/cli.ts": "export {};\n" });
  const runDir = join(root, "run");
  const dumps = join(runDir, COVERAGE_LAYOUT.node);
  mkdirSync(dumps, { recursive: true });
  const script = (rel: string, ranges: readonly CoverageRange[]): object => ({
    scriptId: "1",
    url: pathToFileURL(join(root, rel)).href,
    functions: [{ functionName: "", isBlockCoverage: true, ranges }],
  });
  const everything = run({ positive: true, spare: true });
  // The supervisor ran the whole file; were its hits kept, `spare` would read as executed.
  writeFileSync(
    join(dumps, "coverage-1.json"),
    JSON.stringify({ result: [script("tooling/src/stack/cli.ts", [{ startOffset: 0, endOffset: 10, count: 1 }]), script(SOURCE, everything)] }),
  );
  writeFileSync(join(dumps, "coverage-2.json"), JSON.stringify({ result: [script(SOURCE, run({ positive: true, spare: false }))] }));
  const merged = mergeCoverage(root, [{ suite: "e2e", map: await convertNodeRun(root, runDir) }]);
  expect(merged.unexecuted.flatMap((file) => file.functions)).toEqual([{ name: "spare", line: 7 }]);
});

test("real Node dumps keep the product process and drop the harness process", { timeout: 30_000 }, async ({ plantedTree }) => {
  const root = await plantedTree({
    [SOURCE]: TEXT,
    "packages/demo/src/main.ts": 'import { pick } from "./pick.ts";\npick(1);\n',
    // The harness calls `spare`; were its process kept, `spare` would read as executed.
    "tooling/src/cli.ts": 'import { pick, spare } from "../../packages/demo/src/pick.ts";\npick(-1);\nspare();\n',
  });
  const runDir = join(root, "run");
  for (const entry of ["packages/demo/src/main.ts", "tooling/src/cli.ts"]) {
    // Node itself writes the dumps, as the e2e server does under `NODE_V8_COVERAGE`.
    execFileSync(process.execPath, [join(root, entry)], {
      env: inheritedProcessEnv(Object.fromEntries([["NODE_V8_COVERAGE", join(runDir, COVERAGE_LAYOUT.node)]])),
    });
  }
  const merged = mergeCoverage(root, [{ suite: "e2e", map: await convertNodeRun(root, runDir) }]);
  expect(merged.unexecuted).toEqual([{ file: SOURCE, functions: [{ name: "spare", line: 7 }], branches: [{ type: "if", line: 2, arm: 1 }] }]);
  // The product entry is listed in scope and fully ran; the harness entry is outside scope either way.
  expect(merged.totals.files).toBe(2);
});

test("a browser chunk's hits land on the Node suite's entries through its inline map", { timeout: 30_000 }, async ({ plantedTree }) => {
  const root = await plantedTree({ [SOURCE]: TEXT });
  const path = join(root, SOURCE);
  // A transformed chunk with a map, sources absolute as the coverage build writes them.
  const built = await transformWithOxc(TEXT, path, { sourcemap: true });
  const map = { ...built.map, sources: [path] };
  const url = "http://127.0.0.1:5173/assets/pick.js";
  const code = `${built.code}\n//# sourceMappingURL=data:application/json;base64,${Buffer.from(JSON.stringify(map)).toString("base64")}\n`;
  const spareAt = code.indexOf("function spare");
  const runDir = join(root, "run");
  mkdirSync(join(runDir, COVERAGE_LAYOUT.browser), { recursive: true });
  mkdirSync(join(runDir, COVERAGE_LAYOUT.sources), { recursive: true });
  writeFileSync(join(runDir, COVERAGE_LAYOUT.sources, sourceFileName(url)), code);
  const segments = flattenHits([
    {
      functionName: "",
      isBlockCoverage: true,
      ranges: [
        { startOffset: 0, endOffset: code.length, count: 1 },
        { startOffset: spareAt, endOffset: code.indexOf("}", spareAt) + 1, count: 1 },
      ],
    },
  ]);
  writeFileSync(
    join(runDir, COVERAGE_LAYOUT.browser, "1-0.json"),
    JSON.stringify({ specs: ["tests/demo/pick.ct.tsx"], scripts: [{ url, source: sourceFileName(url), segments }] }),
  );
  const browser = await convertBrowserRun(runDir);
  expect(browser.specs).toEqual(["tests/demo/pick.ct.tsx"]);
  const node = await converted(root, run({ positive: true, spare: false }));
  const merged = mergeCoverage(root, [
    { suite: "node", map: node },
    { suite: "ct", map: browser.map },
  ]);
  expect(merged.unexecuted.flatMap((file) => file.functions)).toEqual([]);
  expect(merged.projections.ct?.unmatchedFunctions).toBe(0);
});

test("a compiled copy lands on its source function by name and line, or as the one anonymous function on its line", ({ plantedTree }) => {
  return plantedTree({ [SOURCE]: TEXT }).then((root) => {
    const path = join(root, SOURCE);
    const range = (line: number, column: number): { start: { line: number; column: number }; end: { line: number; column: number } } => ({
      start: { line, column },
      end: { line, column: column + 1 },
    });
    const file = (
      fns: readonly { readonly name: string; readonly line: number; readonly decl: number; readonly hit: number }[],
    ): Awaited<ReturnType<typeof istanbulOf>> => ({
      [path]: {
        path,
        fnMap: Object.fromEntries(fns.map((fn, index) => [String(index), { name: fn.name, decl: range(fn.line, fn.decl), loc: range(fn.line, fn.decl) }])),
        f: Object.fromEntries(fns.map((fn, index) => [String(index), fn.hit])),
        branchMap: {},
        b: {},
      },
    });
    // The Node copy names `Stack` at its identifier; the compiled browser copy starts at the `function` keyword. Line 2
    // holds one anonymous callback, line 3 two, so only line 2's moved copy has one place to land.
    const node = file([
      { name: "Stack", line: 1, decl: 16, hit: 0 },
      { name: "(anonymous_1)", line: 2, decl: 30, hit: 0 },
      { name: "(anonymous_2)", line: 3, decl: 10, hit: 0 },
      { name: "(anonymous_3)", line: 3, decl: 40, hit: 0 },
    ]);
    const ct = file([
      { name: "Stack", line: 1, decl: 7, hit: 1 },
      { name: "(anonymous_4)", line: 2, decl: 28, hit: 1 },
      { name: "(anonymous_5)", line: 3, decl: 12, hit: 1 },
    ]);
    const merged = mergeCoverage(root, [
      { suite: "node", map: node },
      { suite: "ct", map: ct },
    ]);
    expect(merged.unexecuted.flatMap((entry) => entry.functions)).toEqual([
      { name: "(anonymous_2)", line: 3 },
      { name: "(anonymous_3)", line: 3 },
    ]);
    expect(merged.projections.ct).toMatchObject({ matchedFunctions: 2, unmatchedFunctions: 1 });
  });
});
